 public static synchronized void updateAll(Context c){try{batchState.set(state(c));}catch(Exception e){return;}try{updateBatch(c);}finally{batchState.remove();}}
 static void updateBatch(Context c){AppWidgetManager m=AppWidgetManager.getInstance(c);String[] providers={"Hero","HeroLarge","NextPrayer","PrayerBar","Schedule","DayPrayer","Pill","Clock","Hijri","Gregorian"};for(String kind:providers)for(int id:m.getAppWidgetIds(new ComponentName(c,"com.example.widget."+kind+"WidgetProvider"))){try{Bundle b=m.getAppWidgetOptions(id);int dw=kind.startsWith("Hero")||kind.equals("Schedule")?330:kind.equals("Clock")?250:kind.equals("Hijri")||kind.equals("Gregorian")?90:110;int dh=kind.equals("HeroLarge")?160:90;int wd=Math.max(50,b.getInt(AppWidgetManager.OPTION_APPWIDGET_MIN_WIDTH,dw)),ht=Math.max(kind.equals("Hero")?40:60,b.getInt(AppWidgetManager.OPTION_APPWIDGET_MIN_HEIGHT,dh));RemoteViews v=new RemoteViews(c.getPackageName(),res(c,"layout","home_prayer_art"));v.setImageViewBitmap(res(c,"id","home_prayer_image"),renderKind(c,kind.equals("HeroLarge")?"Hero":kind,wd,ht,id));v.setOnClickPendingIntent(res(c,"id","home_prayer_image"),open(c,!kind.equals("Hijri")&&!kind.equals("Gregorian")));m.updateAppWidget(id,v);}catch(Exception e){android.util.Log.e("WathakkerHome","Update failed: "+kind,e);}}}
 static long[] times(Context c,Calendar day)throws Exception{Method m=LockWidgets.class.getDeclaredMethod("times",Context.class,Calendar.class);m.setAccessible(true);return (long[])m.invoke(null,c,day);}
 static String lang(Context c){String x=c.getSharedPreferences("app_prefs",0).getString("language","ar");return x==null?"ar":x;}
 static boolean ar(Context c){return lang(c).startsWith("ar");}
 static boolean rtl(Context c){String x=lang(c);return x.startsWith("ar")||x.startsWith("ur");}
 static Typeface face(Context c,boolean bold){return face(c,bold,rtl(c));}
 static Typeface face(Context c,boolean bold,boolean rtl){if(!rtl)return Typeface.create(bold?"sans-serif":"sans-serif-medium",bold?Typeface.BOLD:Typeface.NORMAL);Typeface t=bold?boldFace:regularFace;if(t==null){t=Typeface.createFromAsset(c.getAssets(),"homefonts/expoarabic_"+(bold?"semibold":"medium")+".ttf");if(bold)boldFace=t;else regularFace=t;}return t;}
 static void text(Canvas cv,String s,float x,float y,float width,float size,Typeface f,int color,Layout.Alignment align,float d){TextPaint p=new TextPaint(Paint.ANTI_ALIAS_FLAG);p.setTypeface(f);p.setTextSize(size*d);p.setColor(color);while(p.measureText(s)>Math.max(1,width-2)*d&&p.getTextSize()>6*d)p.setTextSize(p.getTextSize()-.25f*d);if(TextDirectionHeuristics.FIRSTSTRONG_LTR.isRtl(s,0,s.length())){if(align==Layout.Alignment.ALIGN_NORMAL)align=Layout.Alignment.ALIGN_OPPOSITE;else if(align==Layout.Alignment.ALIGN_OPPOSITE)align=Layout.Alignment.ALIGN_NORMAL;}StaticLayout l=StaticLayout.Builder.obtain(s,0,s.length(),p,Math.max(1,(int)(width*d))).setAlignment(align).setTextDirection(TextDirectionHeuristics.FIRSTSTRONG_LTR).setIncludePad(false).setMaxLines(2).build();while(l.getLineCount()>1&&p.getTextSize()>6*d){p.setTextSize(p.getTextSize()-.25f*d);l=StaticLayout.Builder.obtain(s,0,s.length(),p,Math.max(1,(int)(width*d))).setAlignment(align).setTextDirection(TextDirectionHeuristics.FIRSTSTRONG_LTR).setIncludePad(false).setMaxLines(2).build();}cv.save();cv.translate(x*d,y*d-l.getHeight()/2f);l.draw(cv);cv.restore();}
 static void heroText(Canvas cv,String s,float x,float y,float width,float size,Typeface f,int color,Layout.Alignment align,float d){TextPaint p=new TextPaint(Paint.ANTI_ALIAS_FLAG);p.setTypeface(f);p.setTextSize(size*d);p.setColor(color);while(p.measureText(s)>width*d&&p.getTextSize()>8*d*Math.min(1,size/12f))p.setTextSize(p.getTextSize()-.5f*d);if(TextDirectionHeuristics.FIRSTSTRONG_LTR.isRtl(s,0,s.length())){if(align==Layout.Alignment.ALIGN_NORMAL)align=Layout.Alignment.ALIGN_OPPOSITE;else if(align==Layout.Alignment.ALIGN_OPPOSITE)align=Layout.Alignment.ALIGN_NORMAL;}StaticLayout l=StaticLayout.Builder.obtain(s,0,s.length(),p,Math.max(1,(int)(width*d))).setAlignment(align).setTextDirection(TextDirectionHeuristics.FIRSTSTRONG_LTR).setIncludePad(false).setMaxLines(1).build();cv.save();cv.translate(x*d,y*d-l.getHeight()/2f);l.draw(cv);cv.restore();}
 public static String tm(long x,String code){Calendar c=Calendar.getInstance();c.setTimeInMillis(x);com.example.ui.i18n.L10n l10n=com.example.ui.i18n.L10n.INSTANCE;String marker=c.get(Calendar.AM_PM)==0?l10n.t(com.example.ui.i18n.S.AmMarker):l10n.t(com.example.ui.i18n.S.PmMarker);return "\u2066"+new SimpleDateFormat("h:mm",Locale.ENGLISH).format(new Date(x))+"\u2069 "+marker;}
 public static String durText(long mins,String code){long h=mins/60,m=mins%60;if(code.startsWith("ar")){String hp=h==1?"ساعة":h==2?"ساعتان":h>=3&&h<=10?h+" ساعات":h+" ساعة";String mp=m==1?"دقيقة":m==2?"دقيقتان":m>=3&&m<=10?m+" دقائق":m+" دقيقة";if(h>0&&m>0)return hp+" و"+mp;if(h>0)return hp;if(m>0)return mp;return "أقل من دقيقة";}if(code.startsWith("en")){if(h>0&&m>0)return h+"h "+m+"m";if(h>0)return h+(h==1?" hour":" hours");if(m>0)return m+(m==1?" minute":" minutes");return "<1 min";}String hu,mu;if(code.startsWith("de")){hu="Std.";mu="Min.";}else if(code.startsWith("tr")){hu="sa";mu="dk";}else if(code.startsWith("id")){hu="jam";mu="mnt";}else if(code.startsWith("ru")){hu="ч";mu="мин";}else if(code.startsWith("ur")){hu="گھنٹے";mu="منٹ";}else{hu="h";mu="min";}if(h>0&&m>0)return h+" "+hu+" "+m+" "+mu;if(h>0)return h+" "+hu;if(m>0)return m+" "+mu;return "<1 "+mu;}
 public static String adhanWord(String code){if(code.startsWith("ar"))return "أذان";if(code.startsWith("ur"))return "اذان";return "Adhan";}
 public static String remaining(long mins,String code){return remLabel(code)+" "+durText(mins,code);}
 public static String remLabel(String code){if(code.startsWith("ar"))return "المتبقي";if(code.startsWith("en"))return "Remaining";if(code.startsWith("fr"))return "Reste";if(code.startsWith("de"))return "Verbleibend";if(code.startsWith("es"))return "Quedan";if(code.startsWith("it"))return "Rimangono";if(code.startsWith("tr"))return "Kalan";if(code.startsWith("ur"))return "باقی";if(code.startsWith("id"))return "Tersisa";if(code.startsWith("ru"))return "Осталось";if(code.startsWith("pt"))return "Restam";return "Remaining";}
 static final class State{long now=System.currentTimeMillis(),at,prev;long[] ts;int next,previous;String[] names;String city,day,hijri,greg,hmonth,gmonth,hday,gday,hyear,gyear,code;boolean rtl;}
 static State state(Context c)throws Exception{State s=new State();s.code=lang(c);s.rtl=rtl(c);com.example.ui.i18n.L10n.INSTANCE.init(c);Locale l=new Locale(s.code);Calendar day=Calendar.getInstance();s.ts=times(c,day);com.example.ui.i18n.L10n lx=com.example.ui.i18n.L10n.INSTANCE;s.names=new String[]{lx.t(com.example.ui.i18n.S.PrayerFajr),lx.t(com.example.ui.i18n.S.PrayerShuruq),lx.t(com.example.ui.i18n.S.PrayerDhuhr),lx.t(com.example.ui.i18n.S.PrayerAsr),lx.t(com.example.ui.i18n.S.PrayerMaghrib),lx.t(com.example.ui.i18n.S.PrayerIsha)};s.next=-1;for(int i=0;i<6;i++)if(i!=1&&s.ts[i]>s.now){s.next=i;break;}if(s.next<0){Calendar t=(Calendar)day.clone();t.add(Calendar.DATE,1);s.at=times(c,t)[0];s.next=0;s.prev=s.ts[5];s.previous=5;}else{s.at=s.ts[s.next];s.previous=s.next==2?0:s.next-1;if(s.next==0){Calendar y=(Calendar)day.clone();y.add(Calendar.DATE,-1);s.prev=times(c,y)[5];s.previous=5;}else s.prev=s.ts[s.previous];}s.city=(String)Class.forName("com.example.fajr.data.FajrPreferences").getMethod("getCityNameLocalized",String.class).invoke(Class.forName("com.example.fajr.data.FajrPreferences").getConstructor(Context.class).newInstance(c),s.code);s.day=new SimpleDateFormat("EEEE",l).format(new Date());android.icu.util.IslamicCalendar h=new android.icu.util.IslamicCalendar();h.setCalculationType(android.icu.util.IslamicCalendar.CalculationType.ISLAMIC_UMALQURA);;s.hday=""+h.get(Calendar.DATE);s.hyear=""+h.get(Calendar.YEAR);s.hmonth=com.example.prayer.HijriDate.INSTANCE.monthName(h.get(Calendar.MONTH)+1,s.code);s.hijri=s.hday+" "+s.hmonth;s.greg=new SimpleDateFormat("d MMMM",l).format(new Date());s.gday=new SimpleDateFormat("d",Locale.ENGLISH).format(new Date());s.gmonth=new SimpleDateFormat("MMMM",l).format(new Date());s.gyear=""+day.get(Calendar.YEAR);return s;}
  static int barFillColor(Context c,int id){String k=id>0?c.getSharedPreferences("fajr_prefs",0).getString("widget_bar_color_"+id,null):null;if(k==null)k=c.getSharedPreferences("fajr_prefs",0).getString("widget_bar_color","default");if("amber".equals(k))return 0xFFE5B455;if("blue".equals(k))return 0xFF3E91FF;if("green".equals(k))return 0xFF34C759;return Color.WHITE;}
 static int bgColor(Context c,int id){String k=id>0?c.getSharedPreferences("fajr_prefs",0).getString("widget_bg_color_"+id,null):null;if(k==null)k=c.getSharedPreferences("fajr_prefs",0).getString("widget_bg_color","default");if("black".equals(k))return 0xff000000;if("gray".equals(k))return 0xff2b2b2b;if("blue".equals(k))return 0xff12263d;if("green".equals(k))return 0xff123626;if("white".equals(k))return 0xfff6f6f6;return 0xff171719;}
 static boolean isLight(int bg){int r=(bg>>16)&255,g=(bg>>8)&255,b=bg&255;return 0.299*r+0.587*g+0.114*b>170;}
 static void bar(Canvas cv,Paint p,float pad,float y,float wd,float bh,float fraction,float d,int fill,int track){p.setColor(track);cv.drawRoundRect(new RectF(pad*d,y*d,(wd-pad)*d,(y+bh)*d),bh*d/2,bh*d/2,p);float fw=Math.max(bh,(wd-2*pad)*Math.max(0,Math.min(1,fraction)));p.setColor(fill);cv.drawRoundRect(new RectF((wd-pad-fw)*d,y*d,(wd-pad)*d,(y+bh)*d),bh*d/2,bh*d/2,p);}
 public static Bitmap render(Context c,int wd,int ht){return renderKind(c,"Hero",wd,ht,0);}
 public static Bitmap renderKind(Context c,String kind,int wd,int ht,int id){float d=c.getResources().getDisplayMetrics().density;Bitmap b=Bitmap.createBitmap(Math.max(1,(int)(wd*d)),Math.max(1,(int)(ht*d)),Bitmap.Config.ARGB_8888);Canvas cv=new Canvas(b);Paint p=new Paint(Paint.ANTI_ALIAS_FLAG);int bg=bgColor(c,id);p.setColor(bg);cv.drawRoundRect(new RectF(0,0,wd*d,ht*d),Math.min(24,ht/4f)*d,Math.min(24,ht/4f)*d,p);Typeface med=face(c,false,s.rtl),semi=face(c,true,s.rtl);boolean light=isLight(bg);int white=light?0xff1c1c1e:Color.WHITE,gray=light?0xff63636b:0xffc9c9ce;int dateC=light?0xff6e6e76:0xff96969e;int remainC=light?0xffb47a1e:0xffe5b455;int trackC=light?0xffd8d8de:0xff4c4c4e;try{State s=batchState.get();if(s==null)s=state(c);long mins=Math.max(0,(s.at-s.now)/60000);float pad=Math.min(18,wd*.06f),ww=wd-2*pad;float progress=(s.now-s.prev)/(float)Math.max(1,s.at-s.prev);String remain=remaining(mins,s.code);if(kind.equals("Hero")){boolean compact=true;float nameY=compact?ht*.389f:ht*.283f,barY=compact?ht*.57f:ht*.444f,timeY=compact?ht*(ht<70?.78f:.844f):ht*.602f,dateY=compact?ht*.133f:ht*.75f,countY=compact?ht*.389f:ht-15;if(!compact){heroText(cv,s.city,pad,22,ww*.70f,14,med,gray,Layout.Alignment.ALIGN_NORMAL,d);heroText(cv,s.day,wd-pad-ww*.28f,22,ww*.28f,14,med,gray,Layout.Alignment.ALIGN_OPPOSITE,d);}float side=compact?ww*.22f:ww*.4f;Layout.Alignment la=compact?Layout.Alignment.ALIGN_CENTER:Layout.Alignment.ALIGN_NORMAL,ra=compact?Layout.Alignment.ALIGN_CENTER:Layout.Alignment.ALIGN_OPPOSITE;heroText(cv,s.names[s.next],pad,nameY,side,18*Math.min(1,ht/70f),med,white,la,d);heroText(cv,s.names[s.previous],wd-pad-side,nameY,side,18*Math.min(1,ht/70f),med,white,ra,d);bar(cv,p,pad,barY,wd,compact?Math.min(8,ht*.09f):10,progress,d,barFillColor(c,id),trackC);heroText(cv,tm(s.at,s.code),pad,timeY,side,21*Math.min(1,ht/70f),semi,white,la,d);heroText(cv,tm(s.prev,s.code),wd-pad-side,timeY,side,21*Math.min(1,ht/70f),semi,white,ra,d);float dateWidth=ww*(compact?.48f:.48f);heroText(cv,s.hijri,pad,dateY,dateWidth,12*Math.min(1,ht/70f),med,dateC,Layout.Alignment.ALIGN_NORMAL,d);heroText(cv,s.greg,wd-pad-dateWidth,dateY,dateWidth,12*Math.min(1,ht/70f),med,dateC,Layout.Alignment.ALIGN_OPPOSITE,d);heroText(cv,remain,compact?pad+ww*.24f:pad,countY,compact?ww*.52f:ww,15*Math.min(1,ht/70f),med,remainC,Layout.Alignment.ALIGN_CENTER,d);}
 else if(kind.equals("NextPrayer")||kind.equals("PrayerBar")){boolean square=wd<ht*1.45f;float bh=Math.min(10,ht*.11f);float nameY=kind.equals("PrayerBar")?ht*.21f:square?ht*.13f:ht*.26f,timeY=kind.equals("PrayerBar")?ht*.79f:square?ht*.326f:ht*.493f;text(cv,s.names[s.next],pad,nameY,ww,14*Math.min(1,ht/70f),med,white,Layout.Alignment.ALIGN_CENTER,d);text(cv,tm(s.at,s.code),pad,timeY,ww,(kind.equals("PrayerBar")?16:18)*Math.min(1,ht/70f),semi,white,Layout.Alignment.ALIGN_CENTER,d);if(kind.equals("PrayerBar"))bar(cv,p,pad,ht*.422f,wd,bh,progress,d,barFillColor(c,id),trackC);else if(square){text(cv,remLabel(s.code),pad,ht*.537f,ww,11*Math.min(1,ht/70f),med,gray,Layout.Alignment.ALIGN_CENTER,d);text(cv,durText(mins,s.code),pad,ht*.74f,ww,11*Math.min(1,ht/70f),med,gray,Layout.Alignment.ALIGN_CENTER,d);}else text(cv,remain,pad,ht*.73f,ww,12*Math.min(1,ht/70f),med,gray,Layout.Alignment.ALIGN_CENTER,d);}
 else if(kind.equals("Schedule")){float cell=ww/6;for(int i=0;i<6;i++){float x=s.rtl?wd-pad-cell*(i+1):pad+cell*i;text(cv,s.names[i],x+2,ht*.30f,cell-4,13,med,gray,Layout.Alignment.ALIGN_CENTER,d);text(cv,tm(s.ts[i],s.code),x+2,ht*.69f,cell-4,13,semi,white,Layout.Alignment.ALIGN_CENTER,d);}}
 else if(kind.equals("Clock")){float side=ww*.23f;for(int i=0;i<2;i++){float x=(i==0)==s.rtl?wd-pad-side:pad;text(cv,s.names[i==0?s.next:s.previous],x,ht*.28f,side,13,med,gray,Layout.Alignment.ALIGN_CENTER,d);text(cv,tm(i==0?s.at:s.prev,s.code),x,ht*.70f,side,15,semi,white,Layout.Alignment.ALIGN_CENTER,d);}long sec=Math.max(0,(s.at-s.now)/1000);String clock=String.format(Locale.ENGLISH,"%02d:%02d:%02d",sec/3600,sec/60%60,sec%60);text(cv,clock,pad+side,ht*.5f,ww-2*side,26,semi,white,Layout.Alignment.ALIGN_CENTER,d);}
 else if(kind.equals("DayPrayer")){text(cv,s.day,pad,ht*.33f,ww,20*Math.min(1,ht/60f),med,white,Layout.Alignment.ALIGN_CENTER,d);text(cv,s.names[s.next]+" "+tm(s.at,s.code),pad,ht*.70f,ww,14*Math.min(1,ht/70f),med,gray,Layout.Alignment.ALIGN_CENTER,d);}
 else if(kind.equals("Pill")){text(cv,s.rtl?adhanWord(s.code)+" "+s.names[s.next]:s.names[s.next]+" "+adhanWord(s.code),pad,ht*.32f,ww,15*Math.min(1,ht/60f),med,white,Layout.Alignment.ALIGN_CENTER,d);text(cv,remain,pad,ht*.68f,ww,12*Math.min(1,ht/70f),med,gray,Layout.Alignment.ALIGN_CENTER,d);}
 else{boolean hijri=kind.equals("Hijri");text(cv,hijri?s.hday:s.gday,pad,ht*.25f,ww,26*Math.min(1,ht/70f),semi,white,Layout.Alignment.ALIGN_CENTER,d);text(cv,hijri?s.hmonth:s.gmonth,pad,ht*.55f,ww,14*Math.min(1,ht/70f),med,white,Layout.Alignment.ALIGN_CENTER,d);text(cv,hijri?s.hyear+(s.code.startsWith("ar")?" هـ":" AH"):s.gyear,pad,ht*.80f,ww,12*Math.min(1,ht/70f),med,gray,Layout.Alignment.ALIGN_CENTER,d);}}
 catch(Exception e){android.util.Log.e("WathakkerHome","Render failed",e);text(cv,com.example.lockwidgets.LockWidgets.errText(lang(c)),5,ht/2f,wd-10,12,med,white,Layout.Alignment.ALIGN_CENTER,d);}return b;}
